<style>
.ec15-page:has(.ec15-product-page)>.ec15-header{position:relative;background:#211e1b}
.ec15-product-page{background:#faf9f7}.ec15-product-page .ec15-content{padding:28px 0 72px}.ec15-product-page .ec15-container{max-width:1320px}.ec15-product-breadcrumb{display:flex;gap:12px;flex-wrap:wrap;color:#7b746e;font-size:12px;line-height:1.8;margin-bottom:30px}.ec15-product-breadcrumb a:hover{color:var(--ec15-copper)}.ec15-product-detail{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(28px,4vw,64px);align-items:start}.ec15-product-visual{margin:0;background:#fff;border:1px solid #eee8e1;border-radius:18px;overflow:hidden}.ec15-product-visual img{aspect-ratio:1;object-fit:contain;width:100%;padding:24px}.ec15-product-info{min-width:0;padding:12px 0}.ec15-product-eyebrow{font-size:11px;font-weight:700;letter-spacing:.18em;color:#966143}.ec15-product-info h1{font-size:clamp(26px,2.7vw,40px);line-height:1.25;letter-spacing:-.035em;margin:14px 0 12px}.ec15-product-sku{font-size:12px;color:#817a73}.ec15-product-sku strong{font-weight:500;color:#49423c}.ec15-product-price{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:24px 0;padding:22px 0;border-top:1px solid #e7e0d9;border-bottom:1px solid #e7e0d9}.ec15-product-price>strong{font-size:32px;letter-spacing:-.04em;color:#9b603e}.ec15-product-price small{font-size:20px;margin-left:4px}.ec15-product-price del{font-size:15px;color:#8a837c}.ec15-product-discount{padding:5px 9px;background:#f0e1d5;color:#8b5031;border-radius:5px;font-size:12px;font-weight:700}.ec15-product-summary{color:#625c56;font-size:14px;line-height:1.85;margin:0 0 24px}.ec15-product-purchase>label{display:block;font-size:12px;font-weight:600;margin-bottom:9px}.ec15-product-buyrow{display:flex;gap:14px}.ec15-product-quantity{display:flex;flex:0 0 132px;border:1px solid #d9d0c7;border-radius:8px;overflow:hidden;background:#fff}.ec15-product-quantity button{width:38px;border:0;background:transparent;font:22px Arial;cursor:pointer;color:#40362e}.ec15-product-quantity input{width:54px;min-width:0;text-align:center;border:0;background:transparent;font:14px "EC915 Sans",Arial;appearance:textfield;-moz-appearance:textfield}.ec15-product-quantity input::-webkit-inner-spin-button,.ec15-product-quantity input::-webkit-outer-spin-button{appearance:none;margin:0}.ec15-product-add{display:flex;align-items:center;justify-content:center;gap:10px;flex:1;min-height:52px;padding:14px;border:0;border-radius:8px;background:var(--ec15-copper);color:#fff;font:700 13px "EC915 Sans",Arial;cursor:pointer}.ec15-product-add:hover{background:#995d3c}.ec15-product-advice{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;padding:16px;margin-top:14px;border:1px solid #ded4ca;border-radius:8px;background:transparent;color:#554537;font:600 13px "EC915 Sans",Arial;cursor:pointer}.ec15-product-note{font-size:11px;color:#817a73;line-height:1.7;margin:12px 0 26px}.ec15-product-description{border-top:1px solid #e7e0d9;padding-top:24px}.ec15-product-description h2{font-size:17px;margin:0 0 12px}.ec15-product-description .ec15-prose{font-size:14px;color:#625c56;line-height:1.9}.ec15-product-info button:focus-visible,.ec15-product-quantity input:focus-visible{outline:2px solid #966143;outline-offset:3px}
@media(max-width:820px){.ec15-product-detail{grid-template-columns:1fr;gap:24px}.ec15-product-visual{max-width:600px;width:100%;margin:auto}.ec15-product-info{padding:0}.ec15-product-breadcrumb{margin-bottom:20px}.ec15-product-page .ec15-content{padding-top:20px}.ec15-product-price{margin:18px 0}.ec15-product-price>strong{font-size:28px}}
@media(max-width:380px){.ec15-product-buyrow{flex-wrap:wrap}.ec15-product-add{flex-basis:100%}}
</style>
